#include "learning_queue.h"
#include <filesystem>
#include <fstream>
#include <iostream>
#include <thread>
using namespace wangshu;
static int passed=0,failed=0;static LONG pins=0;
static void expect(bool value,const char* why){if(!value)throw std::runtime_error(why);}
static void test(const char* label,const std::function<void()>& run){try{run();++passed;std::cout<<"PASS "<<label<<std::endl;}catch(const std::exception& e){++failed;std::cout<<"FAIL "<<label<<" :: "<<e.what()<<std::endl;}}
static std::wstring guid(){GUID id{};CoCreateGuid(&id);wchar_t value[40];StringFromGUID2(id,value,40);return value;}
struct Event{HANDLE value=CreateEventW(nullptr,TRUE,FALSE,nullptr);~Event(){if(value)CloseHandle(value);}void signal(){SetEvent(value);}bool wait(DWORD ms=5000){return WaitForSingleObject(value,ms)==WAIT_OBJECT_0;}};
static std::wstring mutexName(const std::wstring& path){std::vector<wchar_t> full(32768);DWORD n=GetFullPathNameW(path.c_str(),full.size(),full.data(),nullptr);expect(n&&n<full.size(),"Owned mutex path invalid");unsigned long long hash=1469598103934665603ULL;for(DWORD i=0;i<n;++i){auto c=full[i];if(c>=L'A'&&c<=L'Z')c+=32;if(c==L'/')c=L'\\';hash^=static_cast<unsigned short>(c);hash*=1099511628211ULL;}return L"Local\\WangshuImePersonal-"+std::to_wstring(hash);}
struct HeldMutex {
    Event ready,release;std::thread thread;bool owned=false;
    explicit HeldMutex(const std::wstring& path):thread([&,path]{HANDLE mutex=CreateMutexW(nullptr,FALSE,mutexName(path).c_str());if(mutex){DWORD value=WaitForSingleObject(mutex,2000);owned=value==WAIT_OBJECT_0||value==WAIT_ABANDONED;}ready.signal();release.wait(10000);if(mutex){if(owned)ReleaseMutex(mutex);CloseHandle(mutex);}}){bool signalled=ready.wait();if(!signalled||!owned){release.signal();thread.join();throw std::runtime_error("Owned cross-thread mutex fixture failed");}}
    ~HeldMutex(){release.signal();if(thread.joinable())thread.join();}
    void unlock(){release.signal();if(thread.joinable())thread.join();}
};
static LearningQueueStats drained(ConfirmedLearningQueue& queue){auto end=GetTickCount64()+6500;auto stats=queue.stats();while((stats.pending||stats.callbacks)&&GetTickCount64()<end){Sleep(5);stats=queue.stats();}expect(!stats.pending&&!stats.callbacks,"Owned background queue failed bounded drain");return stats;}
int wmain(int argc,wchar_t** argv){if(argc!=2)return 2;auto directory=std::filesystem::path(argv[1])/guid();std::filesystem::create_directories(directory);auto make=[&](const wchar_t* file){WindowsPersonalStore store((directory/file).wstring());auto empty=store.readLearningFresh();store.modifyLearning(empty.revision,[](LearningData& data){data.enabled=true;});return store.path();};
    test("cancel-before-claim rejects old generation without waiting",[]{LearningCommitFence fence;auto old=fence.token();expect(!fence.cancel()&&!fence.claim(old),"Cancelled generation could claim publication");expect(fence.current(fence.token()),"New generation not usable");});
    test("claim-before-cancel remains owned and release preserves new generation",[]{LearningCommitFence fence;auto old=fence.token();expect(fence.claim(old)&&fence.cancel(),"Claim was not ordered before cancellation");auto next=fence.token();expect(next!=old&&!fence.current(next),"Claim bit lost or new generation not advanced");fence.releaseClaim();expect(fence.current(next)&&!fence.claim(old)&&fence.claim(next),"Release restored stale generation or blocked new claim");fence.releaseClaim();});
    test("32 competing claim/cancel pairs have one publication linearization",[]{for(int i=0;i<32;++i){LearningCommitFence fence;auto token=fence.token();std::atomic<bool> start{false};bool claimed=false,cancelSawClaim=false;std::thread a([&]{while(!start.load())std::this_thread::yield();claimed=fence.claim(token);});std::thread b([&]{while(!start.load())std::this_thread::yield();cancelSawClaim=fence.cancel();});start.store(true);a.join();b.join();expect(claimed==cancelSawClaim,"Claim succeeded after cancellation linearized");if(claimed)fence.releaseClaim();}});
    test("prepared real file is not replaced or backed up after cancellation",[&]{auto path=make(L"prepared.json");WindowsPersonalStore store(path);auto state=store.readLearningFresh();auto before=WindowsPersonalStore::readExternal(store.learningPath());LearningCommitFence fence;auto token=fence.token();Event ready,proceed;bool discarded=false;std::exception_ptr error;std::thread writer([&]{try{LearningWriteGate gate{[&]{return fence.current(token);},[&]{ready.signal();if(!proceed.wait())throw std::runtime_error("Test release timeout");return fence.claim(token);}};store.modifyLearning(state.revision,[](LearningData& data){data.record("test","cancelled",100);},&gate);}catch(const LearningDiscarded&){discarded=true;}catch(...){error=std::current_exception();}});bool atClaim=ready.wait();bool claimed=fence.cancel();proceed.signal();writer.join();if(error)std::rethrow_exception(error);expect(atClaim&&!claimed&&discarded&&WindowsPersonalStore::readExternal(store.learningPath())==before&&!std::filesystem::exists(store.learningPath()+L".bak"),"Cancelled prepared write published data or rotated backup");});
    test("claimed real file save may finish after nonblocking cancellation",[&]{auto path=make(L"claimed.json");WindowsPersonalStore store(path);auto state=store.readLearningFresh();LearningCommitFence fence;auto token=fence.token();Event ready,proceed;bool claimed=false,saved=false;std::exception_ptr error;std::thread writer([&]{try{LearningWriteGate gate{[&]{return fence.current(token);},[&]{claimed=fence.claim(token);ready.signal();if(!proceed.wait())throw std::runtime_error("Test release timeout");return claimed;}};store.modifyLearning(state.revision,[](LearningData& data){data.record("test","earlier-confirmed",100);},&gate);saved=true;}catch(...){error=std::current_exception();}if(claimed)fence.releaseClaim();});bool atClaim=ready.wait();bool orderedBefore=fence.cancel();auto next=fence.token();proceed.signal();writer.join();if(error)std::rethrow_exception(error);auto actual=store.readLearningFresh();expect(atClaim&&orderedBefore&&saved&&actual.data.entries.size()==1&&actual.data.entries[0].text=="earlier-confirmed"&&fence.current(next),"Earlier claimed commit was incorrectly revoked or generation lost");});
    test("actual threadpool queue saves confirmed term and balances module counters",[&]{auto path=make(L"pool.json");WindowsPersonalStore store(path);ConfirmedLearningQueue queue(+[]{InterlockedIncrement(&pins);},+[]{InterlockedDecrement(&pins);});expect(queue.enqueue({path,"test","selected",store.readLearningFresh().revision}),"Existing Windows threadpool submission failed");auto stats=drained(queue);expect(stats.saved==1&&!stats.failed&&store.readLearningFresh().data.entries[0].count==1&&pins==0,"Threadpool save or lifetime counter mismatch");});
    test("four-item capacity is observable and cancellation preserves canonical data",[&]{auto path=make(L"capacity.json");WindowsPersonalStore store(path);auto state=store.readLearningFresh();auto before=WindowsPersonalStore::readExternal(store.learningPath());HeldMutex hold(store.learningPath());ConfirmedLearningQueue queue;for(int i=0;i<4;++i)expect(queue.enqueue({path,"test","word"+std::to_string(i),state.revision}),"Capacity refused one of first four");expect(!queue.enqueue({path,"test","overflow",state.revision})&&queue.stats().overflow==1,"Fifth task not observably rejected");bool claimed=queue.cancel();hold.unlock();auto stats=drained(queue);expect(!claimed&&!stats.saved&&stats.cancelled==4&&WindowsPersonalStore::readExternal(store.learningPath())==before,"Cancellation published queued data or lost task accounting");});
    test("external revision is never overwritten by queued old snapshot",[&]{auto path=make(L"revision.json");WindowsPersonalStore store(path);auto state=store.readLearningFresh();HeldMutex hold(store.learningPath());ConfirmedLearningQueue queue;expect(queue.enqueue({path,"test","obsolete",state.revision}),"Queue rejected fixture");LearningData replacement=state.data;replacement.enabled=false;auto bytes=replacement.serialize();{std::ofstream out(std::filesystem::path(store.learningPath()),std::ios::binary);out<<bytes;}hold.unlock();auto stats=drained(queue);expect(!stats.saved&&stats.conflicts==1&&WindowsPersonalStore::readExternal(store.learningPath())==bytes,"Old job replaced external disabled preference");});
    test("closed queue accepts no new terms and drains without joining caller",[&]{auto path=make(L"closed.json");WindowsPersonalStore store(path);HeldMutex hold(store.learningPath());ConfirmedLearningQueue queue;queue.enqueue({path,"test","pending",store.readLearningFresh().revision});queue.close();expect(!queue.enqueue({path,"test","after-close",store.readLearningFresh().revision}),"Closed queue accepted work");hold.unlock();auto stats=drained(queue);expect(!stats.saved&&stats.cancelled==1&&store.readLearningFresh().data.entries.empty(),"Closed service published unclaimed word");});
    test("manual pin unpin forget run asynchronously even when auto-learning disabled",[&]{
        auto path=(directory/L"manual.json").wstring();WindowsPersonalStore store(path);auto state=store.readLearningFresh();ConfirmedLearningQueue queue;
        expect(!state.data.enabled,"default should not auto-learn");
        expect(queue.enqueue({path,"test","manual",state.revision,LearningJobAction::Pin}),"pin enqueue");auto a=drained(queue);auto pinned=store.readLearningFresh();expect(a.saved==1&&pinned.data.pinned("test","manual"),"pin not persisted");
        expect(queue.enqueue({path,"test","manual",pinned.revision,LearningJobAction::Unpin}),"unpin enqueue");auto b=drained(queue);auto unpinned=store.readLearningFresh();expect(b.saved==2&&!unpinned.data.pinned("test","manual"),"unpin not persisted");
        expect(queue.enqueue({path,"test","again",unpinned.revision,LearningJobAction::Pin}),"second pin enqueue");drained(queue);auto again=store.readLearningFresh();
        expect(queue.enqueue({path,"test","again",again.revision,LearningJobAction::Forget}),"forget enqueue");auto c=drained(queue);expect(c.saved==4&&store.readLearningFresh().data.entries.empty(),"forget not persisted");
    });
    test("focus or privacy cancel prevents pending manual write without blocking editor",[&]{
        auto path=(directory/L"manual-cancel.json").wstring();WindowsPersonalStore store(path);auto before=store.readLearningFresh();HeldMutex hold(store.learningPath());ConfirmedLearningQueue queue;
        auto started=GetTickCount64();expect(queue.enqueue({path,"test","private",before.revision,LearningJobAction::Pin}),"manual enqueue failed");bool claimed=queue.cancel();auto elapsed=GetTickCount64()-started;hold.unlock();auto stats=drained(queue);
        expect(elapsed<500&&!claimed&&!stats.saved&&stats.cancelled==1&&store.readLearningFresh().revision==before.revision,"cancel blocked, claimed, or published");
    });
    test("manual commands against stale revision are refused without losing first action",[&]{
        auto path=(directory/L"manual-order.json").wstring();WindowsPersonalStore store(path);auto before=store.readLearningFresh();HeldMutex hold(store.learningPath());ConfirmedLearningQueue queue;
        expect(queue.enqueue({path,"test","first",before.revision,LearningJobAction::Pin}),"first action enqueue");expect(queue.enqueue({path,"test","second",before.revision,LearningJobAction::Pin}),"second action enqueue");
        hold.unlock();auto stats=drained(queue);auto after=store.readLearningFresh();expect(stats.saved==1&&stats.conflicts==1&&after.data.pinned("test","first")&&!after.data.pinned("test","second"),"conflict did not preserve ordered first action");
    });
    std::cout<<"RESULT passed="<<passed<<" failed="<<failed<<" total="<<(passed+failed)<<"; real PE Win32 threads/threadpool/files with controlled generated fixtures; real Windows desktop NOT_RUN"<<std::endl;return failed?1:0;
}
